  END;
  BEGIN
    CREATE OR REPLACE TABLE HARVEST.POLICY_REFERENCES AS SELECT POLICY_NAME, POLICY_KIND, REF_DATABASE_NAME, REF_SCHEMA_NAME, REF_ENTITY_NAME, REF_ENTITY_DOMAIN, REF_COLUMN_NAME, TAG_NAME, POLICY_STATUS FROM SNOWFLAKE.ACCOUNT_USAGE.POLICY_REFERENCES;
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'POLICY_REFERENCES', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'POLICY_REFERENCES', 'unavailable', :SQLERRM;
  END;
  BEGIN
    CREATE OR REPLACE TABLE HARVEST.DATA_METRIC_FUNCTION_REFERENCES AS SELECT METRIC_DATABASE_NAME, METRIC_NAME, REF_DATABASE_NAME || '.' || REF_SCHEMA_NAME || '.' || REF_ENTITY_NAME AS REF_ENTITY_NAME, REF_ENTITY_DOMAIN, SCHEDULE, SCHEDULE_STATUS FROM SNOWFLAKE.ACCOUNT_USAGE.DATA_METRIC_FUNCTION_REFERENCES;
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'DATA_METRIC_FUNCTION_REFERENCES', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'DATA_METRIC_FUNCTION_REFERENCES', 'unavailable', :SQLERRM;
  END;
  BEGIN
    CREATE OR REPLACE TABLE HARVEST.DATA_QUALITY_MONITORING_RESULTS AS SELECT MEASUREMENT_TIME, TABLE_DATABASE || '.' || TABLE_SCHEMA || '.' || TABLE_NAME AS TABLE_NAME, METRIC_NAME, VALUE, NULL AS EXPECTATION_VIOLATED FROM SNOWFLAKE.LOCAL.DATA_QUALITY_MONITORING_RESULTS WHERE MEASUREMENT_TIME >= DATEADD(day, -:window_days, CURRENT_DATE()) AND MEASUREMENT_TIME < CURRENT_DATE() + 1;
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'DATA_QUALITY_MONITORING_RESULTS', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'DATA_QUALITY_MONITORING_RESULTS', 'unavailable', :SQLERRM;
  END;
  BEGIN
    SHOW ALERTS IN ACCOUNT;
    CREATE OR REPLACE TABLE HARVEST.ALERTS AS SELECT "name" AS NAME, "database_name" AS DATABASE_NAME, "schema_name" AS SCHEMA_NAME, "state" AS STATE, "condition" AS CONDITION, "action" AS ACTION, CASE WHEN "condition" ILIKE '%METERING%' OR "condition" ILIKE '%CREDITS%' THEN 'credit_anomaly' WHEN "condition" ILIKE '%TASK_HISTORY%' THEN 'task_failure' WHEN "condition" ILIKE '%LOGIN_HISTORY%' THEN 'login_anomaly' ELSE 'other' END AS ALERT_CLASS FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'ALERTS', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'ALERTS', 'unavailable', :SQLERRM;
  END;
  BEGIN
    SHOW SNOWFLAKE.CORE.BUDGET IN ACCOUNT;
    CREATE OR REPLACE TABLE HARVEST.BUDGETS AS SELECT "name" AS NAME, CASE WHEN "name" ILIKE '%CORTEX%' OR "name" ILIKE '%AI%' THEN 'CORTEX' ELSE 'CUSTOM' END AS SCOPE, NULL AS SPENDING_LIMIT, NULL AS OBJECTS FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'BUDGETS', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'BUDGETS', 'unavailable', :SQLERRM;
  END;
  BEGIN
    CREATE OR REPLACE TABLE HARVEST.CORTEX_USAGE_HISTORY AS SELECT q.START_TIME, q.END_TIME, c.FUNCTION_NAME, c.MODEL_NAME, NULL AS AGENT_NAME, q.ROLE_NAME, q.USER_NAME, c.TOKENS, c.TOKEN_CREDITS FROM SNOWFLAKE.ACCOUNT_USAGE.CORTEX_FUNCTIONS_QUERY_USAGE_HISTORY c JOIN SNOWFLAKE.ACCOUNT_USAGE.QUERY_HISTORY q ON q.QUERY_ID = c.QUERY_ID WHERE q.START_TIME >= DATEADD(day, -:window_days, CURRENT_DATE()) AND q.START_TIME < CURRENT_DATE() + 1;
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'CORTEX_USAGE_HISTORY', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'CORTEX_USAGE_HISTORY', 'unavailable', :SQLERRM;
  END;
  BEGIN
    SHOW SEMANTIC VIEWS IN ACCOUNT;
    CREATE OR REPLACE TABLE HARVEST.SEMANTIC_VIEWS AS SELECT "name" AS NAME, "database_name" AS DATABASE_NAME, "schema_name" AS SCHEMA_NAME, LOWER(REGEXP_REPLACE("name", '^SV_', '')) AS KPI_DOMAIN, "comment" AS COMMENT FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'SEMANTIC_VIEWS', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'SEMANTIC_VIEWS', 'unavailable', :SQLERRM;
  END;
  BEGIN
    SHOW CORTEX SEARCH SERVICES IN ACCOUNT;
    CREATE OR REPLACE TABLE HARVEST.CORTEX_SEARCH_SERVICES AS SELECT "name" AS NAME, "database_name" AS DATABASE_NAME, "schema_name" AS SCHEMA_NAME, "source" AS SOURCE_TABLE, "target_lag" AS TARGET_LAG FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'CORTEX_SEARCH_SERVICES', 'ok', NULL;
  EXCEPTION WHEN OTHER THEN
    INSERT INTO CORE.HARVEST_LOG SELECT :run_at, 'CORTEX_SEARCH_SERVICES', 'unavailable', :SQLERRM;
  END;
  RETURN 'harvested';
END;
$$;

CREATE OR REPLACE VIEW DETECTORS._SIZE_CREDITS AS SELECT 'LARGE' AS WAREHOUSE_SIZE, 8.0 AS CREDITS_PER_HOUR UNION ALL SELECT 'MEDIUM' AS WAREHOUSE_SIZE, 4.0 AS CREDITS_PER_HOUR UNION ALL SELECT 'SMALL' AS WAREHOUSE_SIZE, 2.0 AS CREDITS_PER_HOUR UNION ALL SELECT 'X4LARGE' AS WAREHOUSE_SIZE, 128.0 AS CREDITS_PER_HOUR UNION ALL SELECT 'XLARGE' AS WAREHOUSE_SIZE, 16.0 AS CREDITS_PER_HOUR UNION ALL SELECT 'XSMALL' AS WAREHOUSE_SIZE, 1.0 AS CREDITS_PER_HOUR UNION ALL SELECT 'XXLARGE' AS WAREHOUSE_SIZE, 32.0 AS CREDITS_PER_HOUR UNION ALL SELECT 'XXXLARGE' AS WAREHOUSE_SIZE, 64.0 AS CREDITS_PER_HOUR;

CREATE OR REPLACE VIEW DETECTORS._TIER1_TABLES AS SELECT DISTINCT FQ_NAME FROM (SELECT IFF(_u.pos = _u_2.pos_2, _u_2.FQ_NAME, NULL) AS FQ_NAME FROM HARVEST.CLIENT_INPUTS CROSS JOIN TABLE(FLATTEN(INPUT => ARRAY_GENERATE_RANGE(0, (GREATEST(ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]'))) - 1) + 1))) AS _u(seq, key, path, index, pos, this) CROSS JOIN TABLE(FLATTEN(INPUT => FROM_JSON(VALUE, '["VARCHAR"]'))) AS _u_2(seq, key, path, pos_2, FQ_NAME, this) WHERE KEY = 'tier1_tables' AND (_u.pos = _u_2.pos_2 OR (_u.pos > (ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]')) - 1) AND _u_2.pos_2 = (ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]')) - 1))) UNION ALL SELECT OBJECT_DATABASE || '.' || OBJECT_SCHEMA || '.' || OBJECT_NAME AS FQ_NAME FROM HARVEST.TAG_REFERENCES WHERE UPPER(TAG_NAME) = 'TIER' AND LOWER(TAG_VALUE) IN ('tier1', 'tier-1') AND DOMAIN = 'TABLE');

CREATE OR REPLACE VIEW DETECTORS._WAREHOUSE_CREDITS AS SELECT w.WAREHOUSE_NAME, COALESCE(b.BILLED_CREDITS, 0) AS BILLED_CREDITS, COALESCE(b.TOTAL_CREDITS, 0) AS TOTAL_CREDITS, COALESCE(a.ATTRIBUTED_CREDITS, 0) AS ATTRIBUTED_CREDITS FROM HARVEST.WAREHOUSES AS w LEFT JOIN (SELECT WAREHOUSE_NAME, SUM(CREDITS_USED_COMPUTE) AS BILLED_CREDITS, SUM(CREDITS_USED) AS TOTAL_CREDITS FROM HARVEST.WAREHOUSE_METERING_HISTORY GROUP BY WAREHOUSE_NAME) AS b ON b.WAREHOUSE_NAME = w.WAREHOUSE_NAME LEFT JOIN (SELECT WAREHOUSE_NAME, SUM(CREDITS_ATTRIBUTED_COMPUTE) AS ATTRIBUTED_CREDITS FROM HARVEST.QUERY_ATTRIBUTION_HISTORY GROUP BY WAREHOUSE_NAME) AS a ON a.WAREHOUSE_NAME = w.WAREHOUSE_NAME;

CREATE OR REPLACE VIEW DETECTORS._SIGNATURE_COST AS SELECT q.QUERY_PARAMETERIZED_HASH, COUNT(*) AS EXECUTIONS, COALESCE(SUM(a.CREDITS_ATTRIBUTED_COMPUTE), 0) AS CREDITS, MIN(q.WAREHOUSE_NAME) AS WAREHOUSE_NAME, MIN(q.QUERY_TEXT) AS SAMPLE_TEXT FROM HARVEST.QUERY_HISTORY AS q LEFT JOIN HARVEST.QUERY_ATTRIBUTION_HISTORY AS a ON a.QUERY_ID = q.QUERY_ID GROUP BY q.QUERY_PARAMETERIZED_HASH;

-- DX-AI-01: No semantic views for top KPI domains
CREATE OR REPLACE VIEW DETECTORS.DX_AI_01 AS WITH __signals AS (WITH d AS (SELECT IFF(_u.pos = _u_2.pos_2, _u_2.KPI_DOMAIN, NULL) AS KPI_DOMAIN FROM HARVEST.CLIENT_INPUTS CROSS JOIN TABLE(FLATTEN(INPUT => ARRAY_GENERATE_RANGE(0, (GREATEST(ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]'))) - 1) + 1))) AS _u(seq, key, path, index, pos, this) CROSS JOIN TABLE(FLATTEN(INPUT => FROM_JSON(VALUE, '["VARCHAR"]'))) AS _u_2(seq, key, path, pos_2, KPI_DOMAIN, this) WHERE KEY = 'top_kpi_domains' AND (_u.pos = _u_2.pos_2 OR (_u.pos > (ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]')) - 1) AND _u_2.pos_2 = (ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]')) - 1)))) SELECT d.KPI_DOMAIN AS OBJECT_NAME, 'semantic_layer' AS CLUSTER_KEY, (SELECT COUNT(*) FROM HARVEST.SEMANTIC_VIEWS AS s WHERE LOWER(s.KPI_DOMAIN) = LOWER(d.KPI_DOMAIN)) AS SEMANTIC_VIEWS, (SELECT LISTAGG(t.FQ_NAME, ',') WITHIN GROUP (ORDER BY t.FQ_NAME) FROM HARVEST.TABLES AS t JOIN DETECTORS._TIER1_TABLES AS tt ON tt.FQ_NAME = t.FQ_NAME WHERE UPPER(t.TABLE_SCHEMA) = UPPER(d.KPI_DOMAIN)) AS CANDIDATE_TABLES FROM d) SELECT *, COALESCE((SEMANTIC_VIEWS = 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-AI-02: Cortex usage without budgets or dedicated roles
CREATE OR REPLACE VIEW DETECTORS.DX_AI_02 AS WITH __signals AS (WITH u AS (SELECT c.*, COALESCE(us.TYPE, 'PERSON') AS USER_TYPE FROM HARVEST.CORTEX_USAGE_HISTORY AS c LEFT JOIN HARVEST.USERS AS us ON us.NAME = c.USER_NAME) SELECT 'CORTEX' AS OBJECT_NAME, 'ai_governance' AS CLUSTER_KEY, COALESCE(SUM(TOKEN_CREDITS), 0) AS CREDITS, COUNT(*) AS CALLS, COALESCE(AVG(CASE WHEN USER_TYPE = 'PERSON' THEN 1 ELSE 0 END), 0) AS PERSONAL_USAGE_SHARE, COALESCE(AVG(CASE WHEN AGENT_NAME IS NULL THEN 1 ELSE 0 END), 0) AS NON_AGENT_SHARE, LISTAGG(DISTINCT ROLE_NAME, ', ') WITHIN GROUP (ORDER BY ROLE_NAME) AS ROLES, (SELECT COUNT(*) FROM HARVEST.BUDGETS AS b WHERE UPPER(b.SCOPE) LIKE '%CORTEX%' OR UPPER(b.SCOPE) LIKE '%AI%') AS CORTEX_BUDGETS, COALESCE(SUM(TOKEN_CREDITS), 0) / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) * 30 * (1 + 0.25) AS SUGGESTED_MONTHLY_LIMIT FROM u) SELECT *, COALESCE((CREDITS > 0 AND (CORTEX_BUDGETS = 0 OR PERSONAL_USAGE_SHARE > 0.2)), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-AI-03: Low Tier-1 column comment coverage
CREATE OR REPLACE VIEW DETECTORS.DX_AI_03 AS WITH __signals AS (SELECT c.FQ_NAME AS OBJECT_NAME, c.FQ_NAME AS CLUSTER_KEY, COUNT(*) AS COLUMNS_TOTAL, COUNT_IF(NOT c.COMMENT IS NULL AND TRIM(c.COMMENT) <> '') AS COLUMNS_COMMENTED, COUNT_IF(NOT c.COMMENT IS NULL AND TRIM(c.COMMENT) <> '') / COUNT(*) AS COMMENT_COVERAGE, LISTAGG(IFF(c.COMMENT IS NULL OR TRIM(c.COMMENT) = '', c.COLUMN_NAME, NULL), ',') WITHIN GROUP (ORDER BY c.ORDINAL_POSITION) AS UNCOMMENTED_COLUMNS FROM HARVEST.COLUMNS AS c JOIN DETECTORS._TIER1_TABLES AS tt ON tt.FQ_NAME = c.FQ_NAME GROUP BY c.FQ_NAME) SELECT *, COALESCE((COMMENT_COVERAGE < 0.8), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-ARCH-01: Deep view stacks and duplicate tables
CREATE OR REPLACE VIEW DETECTORS.DX_ARCH_01 AS WITH __signals AS (WITH RECURSIVE vdep AS (SELECT REFERENCING_OBJECT_NAME AS V, REFERENCED_OBJECT_NAME AS R, 1 AS DEPTH FROM HARVEST.OBJECT_DEPENDENCIES WHERE UPPER(REFERENCING_OBJECT_DOMAIN) = 'VIEW' UNION ALL SELECT d.V, o.REFERENCED_OBJECT_NAME, d.DEPTH + 1 FROM vdep AS d JOIN HARVEST.OBJECT_DEPENDENCIES AS o ON o.REFERENCING_OBJECT_NAME = d.R AND UPPER(o.REFERENCING_OBJECT_DOMAIN) = 'VIEW' WHERE d.DEPTH < 64), depth AS (SELECT V, MAX(DEPTH) AS VIEW_DEPTH FROM vdep GROUP BY V), reads AS (SELECT ah.OBJECT_NAME, COALESCE(SUM(a.CREDITS_ATTRIBUTED_COMPUTE), 0) AS READ_CREDITS FROM HARVEST.ACCESS_HISTORY AS ah LEFT JOIN HARVEST.QUERY_ATTRIBUTION_HISTORY AS a ON a.QUERY_ID = ah.QUERY_ID WHERE ah.ACCESS_TYPE = 'READ' GROUP BY ah.OBJECT_NAME), t AS (SELECT tb.FQ_NAME, tb.TABLE_ID, tb.CREATED, tb.BYTES, tb.ROW_COUNT, tb.COLUMN_SIGNATURE, CASE WHEN tb.FQ_NAME IN (SELECT FQ_NAME FROM DETECTORS._TIER1_TABLES) THEN 1 ELSE 0 END AS IS_TIER1, COALESCE(s.ACTIVE_BYTES, 0) + COALESCE(s.TIME_TRAVEL_BYTES, 0) + COALESCE(s.FAILSAFE_BYTES, 0) AS STORAGE_BYTES FROM HARVEST.TABLES AS tb LEFT JOIN HARVEST.TABLE_STORAGE_METRICS AS s ON s.FQ_NAME = tb.FQ_NAME), dup AS (SELECT b.FQ_NAME, MIN(a.FQ_NAME) AS DUPLICATE_OF FROM t AS a JOIN t AS b ON a.COLUMN_SIGNATURE = b.COLUMN_SIGNATURE AND a.FQ_NAME <> b.FQ_NAME AND LEAST_IGNORE_NULLS(a.BYTES, b.BYTES) >= 0.95 * GREATEST_IGNORE_NULLS(a.BYTES, b.BYTES) AND LEAST_IGNORE_NULLS(a.ROW_COUNT, b.ROW_COUNT) >= 0.95 * GREATEST_IGNORE_NULLS(a.ROW_COUNT, b.ROW_COUNT) WHERE a.IS_TIER1 > b.IS_TIER1 OR (a.IS_TIER1 = b.IS_TIER1 AND (a.CREATED < b.CREATED OR (a.CREATED = b.CREATED AND a.TABLE_ID < b.TABLE_ID))) GROUP BY b.FQ_NAME) SELECT v.FQ_NAME AS OBJECT_NAME, 'view_depth' AS CLUSTER_KEY, COALESCE(depth.VIEW_DEPTH, 0) AS VIEW_DEPTH, CASE WHEN NOT EXISTS(SELECT 1 FROM HARVEST.OBJECT_DEPENDENCIES AS o WHERE o.REFERENCED_OBJECT_NAME = v.FQ_NAME) THEN 1 ELSE 0 END AS IS_LEAF, CAST(NULL AS VARCHAR) AS DUPLICATE_OF, CAST(0 AS DOUBLE) AS DUPLICATE_TB, COALESCE(reads.READ_CREDITS, 0) AS READ_CREDITS FROM HARVEST.VIEWS AS v LEFT JOIN depth ON depth.V = v.FQ_NAME LEFT JOIN reads ON reads.OBJECT_NAME = v.FQ_NAME UNION ALL SELECT t.FQ_NAME, 'duplicate_table', NULL, NULL, dup.DUPLICATE_OF, CASE WHEN dup.DUPLICATE_OF IS NULL THEN 0 ELSE t.STORAGE_BYTES / 1099511627776 END, 0 FROM t LEFT JOIN dup ON dup.FQ_NAME = t.FQ_NAME) SELECT *, COALESCE(((CLUSTER_KEY = 'view_depth' AND IS_LEAF = 1 AND VIEW_DEPTH > 5) OR (CLUSTER_KEY = 'duplicate_table' AND NOT DUPLICATE_OF IS NULL)), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-BI-01: Duplicate reports
CREATE OR REPLACE VIEW DETECTORS.DX_BI_01 AS WITH __signals AS (WITH sig AS (SELECT QUERY_PARAMETERIZED_HASH, SUM(CREDITS_ATTRIBUTED_COMPUTE) / COUNT(*) AS CREDITS_PER_EXECUTION FROM HARVEST.QUERY_ATTRIBUTION_HISTORY GROUP BY QUERY_PARAMETERIZED_HASH), r AS (SELECT b.*, ROW_NUMBER() OVER (PARTITION BY STRUCTURE_HASH, QUERY_PARAMETERIZED_HASH ORDER BY VIEWS_90D DESC NULLS LAST, REPORT_ID) AS RN, COUNT(*) OVER (PARTITION BY STRUCTURE_HASH, QUERY_PARAMETERIZED_HASH) AS GROUP_SIZE, FIRST_VALUE(REPORT_ID) OVER (PARTITION BY STRUCTURE_HASH, QUERY_PARAMETERIZED_HASH ORDER BY VIEWS_90D DESC NULLS LAST, REPORT_ID) AS KEEP_REPORT, SUM(VIEWS_90D) OVER (PARTITION BY STRUCTURE_HASH, QUERY_PARAMETERIZED_HASH) AS GROUP_VIEWS FROM HARVEST.BI_REPORTS AS b) SELECT r.REPORT_ID AS OBJECT_NAME, r.STRUCTURE_HASH AS CLUSTER_KEY, r.TOOL, r.NAME, r.WORKSPACE, r.OWNER, r.VIEWS_90D, r.REFRESHES_PER_DAY, r.KEEP_REPORT, r.GROUP_SIZE, r.RN, CASE WHEN r.GROUP_VIEWS > 0 THEN r.VIEWS_90D / r.GROUP_VIEWS ELSE 0 END AS VIEW_SHARE, r.QUERY_PARAMETERIZED_HASH, r.REFRESHES_PER_DAY * (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) * COALESCE(sig.CREDITS_PER_EXECUTION, 0) AS REFRESH_CREDITS FROM r LEFT JOIN sig ON sig.QUERY_PARAMETERIZED_HASH = r.QUERY_PARAMETERIZED_HASH) SELECT *, COALESCE((GROUP_SIZE > 1 AND RN > 1), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-BI-02: Conflicting KPI definitions
CREATE OR REPLACE VIEW DETECTORS.DX_BI_02 AS WITH __signals AS (WITH m AS (SELECT KPI_NAME, REPORT_ID, EXPRESSION, SOURCE_COLUMNS, UPPER(REGEXP_REPLACE(EXPRESSION, '\\s+', '', 'g')) AS NORM_EXPR FROM HARVEST.BI_MEASURES), votes AS (SELECT KPI_NAME, NORM_EXPR, MIN(EXPRESSION) AS EXPRESSION, COUNT(DISTINCT REPORT_ID) AS REPORTS, MIN(SOURCE_COLUMNS) AS SOURCE_COLUMNS, ROW_NUMBER() OVER (PARTITION BY KPI_NAME ORDER BY COUNT(DISTINCT REPORT_ID) DESC NULLS LAST, NORM_EXPR) AS RN FROM m GROUP BY KPI_NAME, NORM_EXPR) SELECT m.KPI_NAME AS OBJECT_NAME, m.KPI_NAME AS CLUSTER_KEY, COUNT(DISTINCT m.NORM_EXPR) AS DEFINITIONS, COUNT(DISTINCT m.REPORT_ID) AS REPORTS, LISTAGG(DISTINCT m.EXPRESSION, ' | ') WITHIN GROUP (ORDER BY m.EXPRESSION) AS VARIANTS, LISTAGG(DISTINCT m.REPORT_ID, ', ') WITHIN GROUP (ORDER BY m.REPORT_ID) AS REPORT_IDS, MIN(v.EXPRESSION) AS CERTIFIED_EXPRESSION, (SELECT MIN(t.FQ_NAME) FROM HARVEST.TABLES AS t WHERE t.TABLE_NAME = SPLIT_PART(MIN(v.SOURCE_COLUMNS), '.', 1)) AS CERTIFIED_TABLE FROM m JOIN votes AS v ON v.KPI_NAME = m.KPI_NAME AND v.RN = 1 GROUP BY m.KPI_NAME) SELECT *, COALESCE((DEFINITIONS > 1), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-BI-03: Dashboards whose refresh cost exceeds their use
CREATE OR REPLACE VIEW DETECTORS.DX_BI_03 AS WITH __signals AS (WITH sig AS (SELECT QUERY_PARAMETERIZED_HASH, SUM(CREDITS_ATTRIBUTED_COMPUTE) AS CREDITS FROM HARVEST.QUERY_ATTRIBUTION_HISTORY GROUP BY QUERY_PARAMETERIZED_HASH), r AS (SELECT b.*, CASE WHEN SUM(b.REFRESHES_PER_DAY) OVER (PARTITION BY b.QUERY_PARAMETERIZED_HASH) > 0 THEN b.REFRESHES_PER_DAY / SUM(b.REFRESHES_PER_DAY) OVER (PARTITION BY b.QUERY_PARAMETERIZED_HASH) ELSE 0 END AS REFRESH_SHARE FROM HARVEST.BI_REPORTS AS b) SELECT r.REPORT_ID AS OBJECT_NAME, r.REPORT_ID AS CLUSTER_KEY, r.TOOL, r.NAME, r.OWNER, r.VIEWS_90D, r.REFRESHES_PER_DAY, r.QUERY_PARAMETERIZED_HASH, COALESCE(sig.CREDITS, 0) * r.REFRESH_SHARE AS REPORT_CREDITS, COALESCE(sig.CREDITS, 0) * r.REFRESH_SHARE * (SELECT TRY_TO_DOUBLE(CAST(VALUE AS VARCHAR)) FROM HARVEST.CLIENT_INPUTS WHERE KEY = 'contract_price_per_credit') / GREATEST_IGNORE_NULLS(r.VIEWS_90D, 1) AS COST_PER_VIEW_USD FROM r LEFT JOIN sig ON sig.QUERY_PARAMETERIZED_HASH = r.QUERY_PARAMETERIZED_HASH) SELECT *, COALESCE((COST_PER_VIEW_USD >= 5), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-01: Idle-heavy warehouses
CREATE OR REPLACE VIEW DETECTORS.DX_COST_01 AS WITH __signals AS (SELECT w.WAREHOUSE_NAME AS OBJECT_NAME, 'auto_suspend' AS CLUSTER_KEY, w.WAREHOUSE_SIZE, w.WORKLOAD_CLASS, w.AUTO_SUSPEND, c.BILLED_CREDITS, c.ATTRIBUTED_CREDITS, GREATEST_IGNORE_NULLS(c.BILLED_CREDITS - c.ATTRIBUTED_CREDITS, 0) AS IDLE_CREDITS, CASE WHEN c.BILLED_CREDITS > 0 THEN GREATEST_IGNORE_NULLS(c.BILLED_CREDITS - c.ATTRIBUTED_CREDITS, 0) / c.BILLED_CREDITS ELSE 0 END AS IDLE_SHARE FROM HARVEST.WAREHOUSES AS w JOIN DETECTORS._WAREHOUSE_CREDITS AS c ON c.WAREHOUSE_NAME = w.WAREHOUSE_NAME) SELECT *, COALESCE((IDLE_SHARE >= 0.6 AND AUTO_SUSPEND > 60 AND BILLED_CREDITS > 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-02: Oversized warehouses
CREATE OR REPLACE VIEW DETECTORS.DX_COST_02 AS WITH __signals AS (WITH q AS (SELECT WAREHOUSE_NAME, COUNT(*) AS QUERIES, PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY EXECUTION_TIME) AS EXEC_P95_MS FROM HARVEST.QUERY_HISTORY WHERE NOT WAREHOUSE_NAME IS NULL GROUP BY WAREHOUSE_NAME), l AS (SELECT WAREHOUSE_NAME, AVG(AVG_QUEUED_LOAD) AS AVG_QUEUED_LOAD FROM HARVEST.WAREHOUSE_LOAD_HISTORY GROUP BY WAREHOUSE_NAME) SELECT w.WAREHOUSE_NAME AS OBJECT_NAME, w.WAREHOUSE_NAME AS CLUSTER_KEY, w.WAREHOUSE_SIZE, w.WORKLOAD_CLASS, s.CREDITS_PER_HOUR, (SELECT t.WAREHOUSE_SIZE FROM DETECTORS._SIZE_CREDITS AS t WHERE t.CREDITS_PER_HOUR < s.CREDITS_PER_HOUR ORDER BY t.CREDITS_PER_HOUR DESC NULLS LAST LIMIT 1) AS TARGET_SIZE, (SELECT MAX(t.CREDITS_PER_HOUR) FROM DETECTORS._SIZE_CREDITS AS t WHERE t.CREDITS_PER_HOUR < s.CREDITS_PER_HOUR) AS TARGET_CREDITS_PER_HOUR, COALESCE(q.QUERIES, 0) AS QUERIES, COALESCE(q.EXEC_P95_MS, 0) AS EXEC_P95_MS, COALESCE(l.AVG_QUEUED_LOAD, 0) AS AVG_QUEUED_LOAD, c.BILLED_CREDITS, w.MAX_CLUSTER_COUNT, c.BILLED_CREDITS * (1 - COALESCE((SELECT MAX(t.CREDITS_PER_HOUR) FROM DETECTORS._SIZE_CREDITS AS t WHERE t.CREDITS_PER_HOUR < s.CREDITS_PER_HOUR), s.CREDITS_PER_HOUR) / s.CREDITS_PER_HOUR) AS DOWNSIZE_CREDITS FROM HARVEST.WAREHOUSES AS w JOIN DETECTORS._SIZE_CREDITS AS s ON s.WAREHOUSE_SIZE = w.WAREHOUSE_SIZE JOIN DETECTORS._WAREHOUSE_CREDITS AS c ON c.WAREHOUSE_NAME = w.WAREHOUSE_NAME LEFT JOIN q ON q.WAREHOUSE_NAME = w.WAREHOUSE_NAME LEFT JOIN l ON l.WAREHOUSE_NAME = w.WAREHOUSE_NAME) SELECT *, COALESCE((CREDITS_PER_HOUR >= 4 AND QUERIES > 0 AND EXEC_P95_MS <= 10000 AND AVG_QUEUED_LOAD <= 0.05 AND MAX_CLUSTER_COUNT <= 1 AND NOT TARGET_SIZE IS NULL), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-03: Repeated identical queries bypass the result cache
CREATE OR REPLACE VIEW DETECTORS.DX_COST_03 AS WITH __signals AS (SELECT q.QUERY_PARAMETERIZED_HASH AS OBJECT_NAME, q.QUERY_PARAMETERIZED_HASH AS CLUSTER_KEY, MIN(q.WAREHOUSE_NAME) AS WAREHOUSE_NAME, COUNT(*) AS EXECUTIONS, COUNT(DISTINCT q.QUERY_TEXT) AS DISTINCT_TEXTS, AVG(CASE WHEN q.BYTES_SCANNED = 0 THEN 1 ELSE 0 END) AS RESULT_REUSE_SHARE, MAX(CASE WHEN REGEXP_LIKE(q.QUERY_TEXT, '(?i)(DATEADD\\(\\s*\'?(day|week|month|quarter|year)\'?\\s*,[^;]*CURRENT_TIMESTAMP|RANDOM\\(|UUID_STRING\\(|RANDSTR\\()') THEN 1 ELSE 0 END) AS CACHE_DEFEATING, COALESCE(SUM(a.CREDITS_ATTRIBUTED_COMPUTE), 0) AS CREDITS, MIN(q.QUERY_TEXT) AS SAMPLE_TEXT FROM HARVEST.QUERY_HISTORY AS q LEFT JOIN HARVEST.QUERY_ATTRIBUTION_HISTORY AS a ON a.QUERY_ID = q.QUERY_ID WHERE q.QUERY_TYPE = 'SELECT' AND q.EXECUTION_STATUS = 'SUCCESS' GROUP BY q.QUERY_PARAMETERIZED_HASH) SELECT *, COALESCE((DISTINCT_TEXTS = 1 AND EXECUTIONS >= 500 AND RESULT_REUSE_SHARE <= 0.2 AND CACHE_DEFEATING = 1), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-04: Daily full reloads of large tables
CREATE OR REPLACE VIEW DETECTORS.DX_COST_04 AS WITH __signals AS (WITH w AS (SELECT ah.OBJECT_NAME, q.QUERY_ID, q.QUERY_PARAMETERIZED_HASH, q.START_TIME, q.BYTES_WRITTEN, COALESCE(a.CREDITS_ATTRIBUTED_COMPUTE, 0) AS CREDITS FROM HARVEST.QUERY_HISTORY AS q JOIN HARVEST.ACCESS_HISTORY AS ah ON ah.QUERY_ID = q.QUERY_ID AND ah.ACCESS_TYPE = 'WRITE' LEFT JOIN HARVEST.QUERY_ATTRIBUTION_HISTORY AS a ON a.QUERY_ID = q.QUERY_ID WHERE ARRAY_CONTAINS(CAST(q.QUERY_TYPE AS VARIANT), ['CREATE_TABLE_AS_SELECT', 'INSERT_OVERWRITE', 'TRUNCATE_TABLE'])), src AS (SELECT w.OBJECT_NAME, MIN(r.OBJECT_NAME) AS SOURCE_OBJECT FROM w JOIN HARVEST.ACCESS_HISTORY AS r ON r.QUERY_ID = w.QUERY_ID AND r.ACCESS_TYPE = 'READ' GROUP BY w.OBJECT_NAME) SELECT w.OBJECT_NAME, MIN(w.QUERY_PARAMETERIZED_HASH) AS CLUSTER_KEY, COUNT(*) AS RELOADS, COUNT(DISTINCT CAST(w.START_TIME AS DATE)) AS RELOAD_DAYS, COUNT(DISTINCT CAST(w.START_TIME AS DATE)) / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) AS RELOAD_DAY_SHARE, AVG(w.BYTES_WRITTEN) AS AVG_BYTES_WRITTEN, SUM(w.BYTES_WRITTEN) AS BYTES_REWRITTEN, SUM(w.CREDITS) AS CREDITS, MIN(t.BYTES) AS TABLE_BYTES, MIN(src.SOURCE_OBJECT) AS SOURCE_OBJECT, (SELECT c.COLUMN_NAME FROM HARVEST.COLUMNS AS c WHERE c.FQ_NAME = w.OBJECT_NAME AND c.COLUMN_NAME LIKE '%\\_ID' ESCAPE '\\' ORDER BY c.ORDINAL_POSITION LIMIT 1) AS KEY_COLUMN FROM w LEFT JOIN HARVEST.TABLES AS t ON t.FQ_NAME = w.OBJECT_NAME LEFT JOIN src ON src.OBJECT_NAME = w.OBJECT_NAME GROUP BY w.OBJECT_NAME) SELECT *, COALESCE((RELOAD_DAY_SHARE >= 0.5 AND AVG_BYTES_WRITTEN >= 107374182400), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-05: Serverless creep without benefit
CREATE OR REPLACE VIEW DETECTORS.DX_COST_05 AS WITH __signals AS (WITH s AS (SELECT TABLE_NAME, 'AUTOMATIC_CLUSTERING' AS FEATURE, CREDITS_USED FROM HARVEST.AUTOMATIC_CLUSTERING_HISTORY UNION ALL SELECT TABLE_NAME, 'SEARCH_OPTIMIZATION', CREDITS_USED FROM HARVEST.SEARCH_OPTIMIZATION_HISTORY UNION ALL SELECT TABLE_NAME, 'MATERIALIZED_VIEW', CREDITS_USED FROM HARVEST.MATERIALIZED_VIEW_REFRESH_HISTORY), agg AS (SELECT TABLE_NAME, FEATURE, SUM(CREDITS_USED) AS CREDITS FROM s GROUP BY TABLE_NAME, FEATURE), r AS (SELECT OBJECT_NAME, COUNT(*) AS READS FROM HARVEST.ACCESS_HISTORY WHERE ACCESS_TYPE = 'READ' GROUP BY OBJECT_NAME) SELECT agg.TABLE_NAME AS OBJECT_NAME, agg.TABLE_NAME || ':' || agg.FEATURE AS CLUSTER_KEY, agg.FEATURE, agg.CREDITS, agg.CREDITS / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) * 30 AS CREDITS_PER_MONTH, COALESCE(r.READS, 0) AS READS, CASE WHEN agg.CREDITS > 0 THEN COALESCE(r.READS, 0) / agg.CREDITS ELSE 0 END AS READS_PER_CREDIT FROM agg LEFT JOIN r ON r.OBJECT_NAME = agg.TABLE_NAME) SELECT *, COALESCE((CREDITS_PER_MONTH >= 100 AND READS_PER_CREDIT <= 1), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-06: Storage waste
CREATE OR REPLACE VIEW DETECTORS.DX_COST_06 AS WITH __signals AS (WITH m AS (SELECT t.FQ_NAME, t.TABLE_SCHEMA, t.IS_TRANSIENT, t.RETENTION_TIME, t.CLONE_GROUP_ID, t.CREATED, t.TABLE_ID, DATEDIFF(DAY, t.LAST_ALTERED, (SELECT AS_OF FROM CORE.RUN_CONTEXT)) AS DAYS_SINCE_ALTERED, COALESCE(s.ACTIVE_BYTES, 0) AS ACTIVE_BYTES, COALESCE(s.TIME_TRAVEL_BYTES, 0) AS TIME_TRAVEL_BYTES, COALESCE(s.FAILSAFE_BYTES, 0) AS FAILSAFE_BYTES, COALESCE(s.RETAINED_FOR_CLONE_BYTES, 0) AS RETAINED_FOR_CLONE_BYTES FROM HARVEST.TABLES AS t LEFT JOIN HARVEST.TABLE_STORAGE_METRICS AS s ON s.FQ_NAME = t.FQ_NAME), grp AS (SELECT CLONE_GROUP_ID, COUNT(*) AS MEMBERS, MIN(CREATED) AS FIRST_CREATED FROM HARVEST.TABLES GROUP BY CLONE_GROUP_ID), r AS (SELECT OBJECT_NAME, COUNT(*) AS READS FROM HARVEST.ACCESS_HISTORY WHERE ACCESS_TYPE = 'READ' GROUP BY OBJECT_NAME) SELECT m.FQ_NAME AS OBJECT_NAME, 'staging_retention' AS CLUSTER_KEY, m.IS_TRANSIENT, m.RETENTION_TIME, m.DAYS_SINCE_ALTERED, COALESCE(r.READS, 0) AS READS, m.TIME_TRAVEL_BYTES + m.FAILSAFE_BYTES AS WASTED_BYTES, (m.TIME_TRAVEL_BYTES + m.FAILSAFE_BYTES) / 1099511627776 AS WASTED_TB FROM m LEFT JOIN r ON r.OBJECT_NAME = m.FQ_NAME WHERE REGEXP_LIKE(m.TABLE_SCHEMA, '(?i)^(STAGING|STG|STAGE|LANDING|TMP|TEMP|WORK)$') UNION ALL SELECT m.FQ_NAME, 'stale_clone', m.IS_TRANSIENT, m.RETENTION_TIME, m.DAYS_SINCE_ALTERED, COALESCE(r.READS, 0), m.ACTIVE_BYTES + m.TIME_TRAVEL_BYTES + m.FAILSAFE_BYTES + m.RETAINED_FOR_CLONE_BYTES, (m.ACTIVE_BYTES + m.TIME_TRAVEL_BYTES + m.FAILSAFE_BYTES + m.RETAINED_FOR_CLONE_BYTES) / 1099511627776 FROM m JOIN grp AS g ON g.CLONE_GROUP_ID = m.CLONE_GROUP_ID AND g.MEMBERS > 1 AND m.CREATED > g.FIRST_CREATED LEFT JOIN r ON r.OBJECT_NAME = m.FQ_NAME) SELECT *, COALESCE((WASTED_BYTES >= 10737418240 AND ((CLUSTER_KEY = 'staging_retention' AND (NOT IS_TRANSIENT OR RETENTION_TIME > 1)) OR (CLUSTER_KEY = 'stale_clone' AND DAYS_SINCE_ALTERED >= 180 AND READS = 0))), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-07: Untagged spend
CREATE OR REPLACE VIEW DETECTORS.DX_COST_07 AS WITH __signals AS (WITH tagname AS (SELECT UPPER(COALESCE((SELECT JSON_EXTRACT_PATH_TEXT(VALUE, '') FROM HARVEST.CLIENT_INPUTS WHERE KEY = 'cost_center_tag'), 'COST_CENTER')) AS TAG), tagged AS (SELECT DISTINCT OBJECT_NAME, TAG_DATABASE || '.' || TAG_SCHEMA || '.' || TAG_NAME AS TAG_FQ FROM HARVEST.TAG_REFERENCES, tagname WHERE DOMAIN = 'WAREHOUSE' AND UPPER(TAG_NAME) = tagname.TAG), tot AS (SELECT SUM(TOTAL_CREDITS) AS ALL_CREDITS FROM DETECTORS._WAREHOUSE_CREDITS) SELECT w.WAREHOUSE_NAME AS OBJECT_NAME, 'cost_center' AS CLUSTER_KEY, c.TOTAL_CREDITS AS CREDITS, CASE WHEN tot.ALL_CREDITS > 0 THEN c.TOTAL_CREDITS / tot.ALL_CREDITS ELSE 0 END AS SPEND_SHARE, CASE WHEN t.OBJECT_NAME IS NULL THEN 0 ELSE 1 END AS HAS_COST_CENTER, COALESCE((SELECT MIN(TAG_FQ) FROM tagged), 'GOVERNANCE.TAGS.' || (SELECT TAG FROM tagname)) AS TAG_FQ FROM HARVEST.WAREHOUSES AS w JOIN DETECTORS._WAREHOUSE_CREDITS AS c ON c.WAREHOUSE_NAME = w.WAREHOUSE_NAME CROSS JOIN tot LEFT JOIN tagged AS t ON t.OBJECT_NAME = w.WAREHOUSE_NAME) SELECT *, COALESCE((HAS_COST_CENTER = 0 AND CREDITS > 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-COST-08: Capacity commitment mis-sized
CREATE OR REPLACE VIEW DETECTORS.DX_COST_08 AS WITH __signals AS (WITH m AS (SELECT SUM(CREDITS_BILLED) AS WINDOW_CREDITS FROM HARVEST.METERING_DAILY_HISTORY), c AS (SELECT CAST(JSON_EXTRACT_PATH_TEXT(VALUE, 'annual_credits') AS DOUBLE) AS COMMIT_CREDITS FROM HARVEST.CLIENT_INPUTS WHERE KEY = 'capacity_commitment') SELECT 'ACCOUNT' AS OBJECT_NAME, 'capacity' AS CLUSTER_KEY, m.WINDOW_CREDITS, m.WINDOW_CREDITS / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) * 365 AS FORECAST_ANNUAL_CREDITS, c.COMMIT_CREDITS, (c.COMMIT_CREDITS - m.WINDOW_CREDITS / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) * 365) / c.COMMIT_CREDITS AS COMMIT_VARIANCE, GREATEST_IGNORE_NULLS(c.COMMIT_CREDITS - m.WINDOW_CREDITS / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) * 365, 0) AS OVER_COMMIT_CREDITS, GREATEST_IGNORE_NULLS(m.WINDOW_CREDITS / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) * 365 - c.COMMIT_CREDITS, 0) AS OVERAGE_CREDITS FROM m CROSS JOIN c WHERE c.COMMIT_CREDITS > 0) SELECT *, COALESCE((ABS(COMMIT_VARIANCE) >= 0.15), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-GOV-01: Tier-1 objects without owner or description
CREATE OR REPLACE VIEW DETECTORS.DX_GOV_01 AS WITH __signals AS (WITH tagname AS (SELECT UPPER(COALESCE((SELECT JSON_EXTRACT_PATH_TEXT(VALUE, '') FROM HARVEST.CLIENT_INPUTS WHERE KEY = 'owner_tag'), 'DATA_OWNER')) AS TAG), owners AS (SELECT OBJECT_DATABASE || '.' || OBJECT_SCHEMA || '.' || OBJECT_NAME AS FQ_NAME, TAG_DATABASE || '.' || TAG_SCHEMA || '.' || TAG_NAME AS TAG_FQ, TAG_VALUE FROM HARVEST.TAG_REFERENCES, tagname WHERE DOMAIN = 'TABLE' AND UPPER(TAG_NAME) = tagname.TAG), writers AS (SELECT OBJECT_NAME, USER_NAME, COUNT(*) AS N, ROW_NUMBER() OVER (PARTITION BY OBJECT_NAME ORDER BY COUNT(*) DESC NULLS LAST, USER_NAME) AS RN FROM HARVEST.ACCESS_HISTORY WHERE ACCESS_TYPE = 'WRITE' GROUP BY OBJECT_NAME, USER_NAME) SELECT t.FQ_NAME AS OBJECT_NAME, COALESCE(w.USER_NAME, t.TABLE_OWNER) AS CLUSTER_KEY, CASE WHEN o.TAG_VALUE IS NULL THEN 0 ELSE 1 END AS HAS_OWNER_TAG, CASE WHEN t.COMMENT IS NULL OR TRIM(t.COMMENT) = '' THEN 0 ELSE 1 END AS HAS_COMMENT, COALESCE(w.USER_NAME, t.TABLE_OWNER) AS SUGGESTED_OWNER, COALESCE((SELECT MIN(TAG_FQ) FROM owners), 'GOVERNANCE.TAGS.' || (SELECT TAG FROM tagname)) AS OWNER_TAG_FQ FROM HARVEST.TABLES AS t JOIN DETECTORS._TIER1_TABLES AS tt ON tt.FQ_NAME = t.FQ_NAME LEFT JOIN owners AS o ON o.FQ_NAME = t.FQ_NAME LEFT JOIN writers AS w ON w.OBJECT_NAME = t.FQ_NAME AND w.RN = 1) SELECT *, COALESCE((HAS_OWNER_TAG = 0 OR HAS_COMMENT = 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-GOV-02: Tier-1 tables without data-quality monitoring
CREATE OR REPLACE VIEW DETECTORS.DX_GOV_02 AS WITH __signals AS (SELECT t.FQ_NAME AS OBJECT_NAME, t.FQ_NAME AS CLUSTER_KEY, (SELECT COUNT(*) FROM HARVEST.DATA_METRIC_FUNCTION_REFERENCES AS d WHERE d.REF_ENTITY_NAME = t.FQ_NAME AND COALESCE(d.SCHEDULE_STATUS, 'STARTED') = 'STARTED') AS DMF_COUNT, (SELECT c.COLUMN_NAME FROM HARVEST.COLUMNS AS c WHERE c.FQ_NAME = t.FQ_NAME ORDER BY c.ORDINAL_POSITION LIMIT 1) AS KEY_COLUMN FROM HARVEST.TABLES AS t JOIN DETECTORS._TIER1_TABLES AS tt ON tt.FQ_NAME = t.FQ_NAME) SELECT *, COALESCE((DMF_COUNT = 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-GOV-03: Unused objects
CREATE OR REPLACE VIEW DETECTORS.DX_GOV_03 AS WITH __signals AS (WITH la AS (SELECT OBJECT_NAME, MAX(QUERY_START_TIME) AS LAST_ACCESS FROM HARVEST.ACCESS_HISTORY GROUP BY OBJECT_NAME) SELECT t.FQ_NAME AS OBJECT_NAME, 'archive' AS CLUSTER_KEY, t.TABLE_CATALOG, t.TABLE_NAME, DATEDIFF(DAY, t.LAST_ALTERED, (SELECT AS_OF FROM CORE.RUN_CONTEXT)) AS DAYS_SINCE_ALTERED, la.LAST_ACCESS, CASE WHEN la.LAST_ACCESS IS NULL THEN 1 ELSE 0 END AS NO_ACCESS_IN_WINDOW, COALESCE(s.ACTIVE_BYTES, 0) + COALESCE(s.TIME_TRAVEL_BYTES, 0) + COALESCE(s.FAILSAFE_BYTES, 0) AS STORAGE_BYTES, (COALESCE(s.ACTIVE_BYTES, 0) + COALESCE(s.TIME_TRAVEL_BYTES, 0) + COALESCE(s.FAILSAFE_BYTES, 0)) / 1099511627776 AS STORAGE_TB FROM HARVEST.TABLES AS t LEFT JOIN la ON la.OBJECT_NAME = t.FQ_NAME LEFT JOIN HARVEST.TABLE_STORAGE_METRICS AS s ON s.FQ_NAME = t.FQ_NAME) SELECT *, COALESCE((NO_ACCESS_IN_WINDOW = 1 AND DAYS_SINCE_ALTERED >= 180), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-OPS-01: Production DDL outside IaC/CI
CREATE OR REPLACE VIEW DETECTORS.DX_OPS_01 AS WITH __signals AS (WITH prod AS (SELECT IFF(_u.pos = _u_2.pos_2, _u_2.DB, NULL) AS DB FROM HARVEST.CLIENT_INPUTS CROSS JOIN TABLE(FLATTEN(INPUT => ARRAY_GENERATE_RANGE(0, (GREATEST(ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]'))) - 1) + 1))) AS _u(seq, key, path, index, pos, this) CROSS JOIN TABLE(FLATTEN(INPUT => FROM_JSON(VALUE, '["VARCHAR"]'))) AS _u_2(seq, key, path, pos_2, DB, this) WHERE KEY = 'production_databases' AND (_u.pos = _u_2.pos_2 OR (_u.pos > (ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]')) - 1) AND _u_2.pos_2 = (ARRAY_SIZE(FROM_JSON(VALUE, '["VARCHAR"]')) - 1)))) SELECT q.USER_NAME AS OBJECT_NAME, q.USER_NAME AS CLUSTER_KEY, COUNT(*) AS DDL_STATEMENTS, COUNT(DISTINCT CAST(q.START_TIME AS DATE)) AS DDL_DAYS, AVG(CASE WHEN REGEXP_LIKE(COALESCE(q.QUERY_TAG, '') || ' ' || COALESCE(q.CLIENT_APPLICATION_ID, ''), '(?i)(terraform|schemachange|dbt|flyway|liquibase|github|gitlab|azure ?devops|ci)') THEN 1 ELSE 0 END) AS IAC_SHARE, LISTAGG(DISTINCT q.QUERY_TYPE, ', ') WITHIN GROUP (ORDER BY q.QUERY_TYPE) AS DDL_TYPES, LISTAGG(DISTINCT q.CLIENT_APPLICATION_ID, ', ') WITHIN GROUP (ORDER BY q.CLIENT_APPLICATION_ID) AS CLIENT_APPS FROM HARVEST.QUERY_HISTORY AS q WHERE REGEXP_LIKE(q.QUERY_TYPE, '^(CREATE|ALTER|DROP|RENAME)_') AND NOT ARRAY_CONTAINS(CAST(q.QUERY_TYPE AS VARIANT), ['CREATE_TABLE_AS_SELECT']) AND (q.DATABASE_NAME IN (SELECT DB FROM prod) OR NOT EXISTS(SELECT 1 FROM prod)) GROUP BY q.USER_NAME) SELECT *, COALESCE((IAC_SHARE < 0.8 AND DDL_STATEMENTS >= 3), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-OPS-02: No alerting for credit spikes or failed Tier-1 tasks
CREATE OR REPLACE VIEW DETECTORS.DX_OPS_02 AS WITH __signals AS (WITH req AS (SELECT IFF(_u.pos = _u_2.pos_2, _u_2.ALERT_CLASS, NULL) AS ALERT_CLASS FROM TABLE(FLATTEN(INPUT => ARRAY_GENERATE_RANGE(0, (GREATEST(ARRAY_SIZE(['credit_anomaly', 'task_failure'])) - 1) + 1))) AS _u(seq, key, path, index, pos, this) CROSS JOIN TABLE(FLATTEN(INPUT => ['credit_anomaly', 'task_failure'])) AS _u_2(seq, key, path, pos_2, ALERT_CLASS, this) WHERE _u.pos = _u_2.pos_2 OR (_u.pos > (ARRAY_SIZE(['credit_anomaly', 'task_failure']) - 1) AND _u_2.pos_2 = (ARRAY_SIZE(['credit_anomaly', 'task_failure']) - 1))), have AS (SELECT DISTINCT ALERT_CLASS FROM HARVEST.ALERTS WHERE LOWER(COALESCE(STATE, 'started')) = 'started') SELECT 'ACCOUNT' AS OBJECT_NAME, 'alerting' AS CLUSTER_KEY, (SELECT COUNT(*) FROM req WHERE NOT ALERT_CLASS IN (SELECT ALERT_CLASS FROM have)) AS MISSING_ALERT_CLASSES, (SELECT LISTAGG(ALERT_CLASS, ',') WITHIN GROUP (ORDER BY ALERT_CLASS) FROM req WHERE NOT ALERT_CLASS IN (SELECT ALERT_CLASS FROM have)) AS MISSING_LIST, (SELECT COUNT(*) FROM HARVEST.RESOURCE_MONITORS WHERE UPPER(LEVEL) = 'ACCOUNT') AS ACCOUNT_MONITORS, (SELECT COUNT(*) FROM HARVEST.WAREHOUSES WHERE RESOURCE_MONITOR IS NULL) AS UNMONITORED_WAREHOUSES, (SELECT COUNT(*) FROM HARVEST.WAREHOUSES) AS WAREHOUSES) SELECT *, COALESCE((MISSING_ALERT_CLASSES > 0 OR ACCOUNT_MONITORS = 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-PERF-01: Queueing on interactive warehouses at peak
CREATE OR REPLACE VIEW DETECTORS.DX_PERF_01 AS WITH __signals AS (WITH l AS (SELECT WAREHOUSE_NAME, COUNT_IF(AVG_QUEUED_LOAD >= 0.5) AS QUEUED_HOURS, MAX(AVG_QUEUED_LOAD) AS MAX_QUEUED_LOAD FROM HARVEST.WAREHOUSE_LOAD_HISTORY GROUP BY WAREHOUSE_NAME), q AS (SELECT WAREHOUSE_NAME, SUM(QUEUED_OVERLOAD_TIME) / 3600000 AS USER_HOURS_QUEUED, COUNT_IF(QUEUED_OVERLOAD_TIME > 0) AS QUEUED_QUERIES FROM HARVEST.QUERY_HISTORY GROUP BY WAREHOUSE_NAME) SELECT w.WAREHOUSE_NAME AS OBJECT_NAME, w.WAREHOUSE_NAME AS CLUSTER_KEY, w.WORKLOAD_CLASS, w.MIN_CLUSTER_COUNT, w.MAX_CLUSTER_COUNT, w.SCALING_POLICY, CASE WHEN ARRAY_CONTAINS(CAST(w.WORKLOAD_CLASS AS VARIANT), ['bi', 'adhoc', 'agents']) THEN 1 ELSE 0 END AS INTERACTIVE, COALESCE(l.QUEUED_HOURS, 0) AS QUEUED_HOURS, COALESCE(l.MAX_QUEUED_LOAD, 0) AS MAX_QUEUED_LOAD, COALESCE(q.USER_HOURS_QUEUED, 0) AS USER_HOURS_QUEUED, COALESCE(q.QUEUED_QUERIES, 0) AS QUEUED_QUERIES FROM HARVEST.WAREHOUSES AS w LEFT JOIN l ON l.WAREHOUSE_NAME = w.WAREHOUSE_NAME LEFT JOIN q ON q.WAREHOUSE_NAME = w.WAREHOUSE_NAME) SELECT *, COALESCE((INTERACTIVE = 1 AND QUEUED_HOURS >= 10 AND MAX_CLUSTER_COUNT < 3), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-PERF-02: Spilling to local or remote storage
CREATE OR REPLACE VIEW DETECTORS.DX_PERF_02 AS WITH __signals AS (SELECT q.QUERY_PARAMETERIZED_HASH AS OBJECT_NAME, q.QUERY_PARAMETERIZED_HASH AS CLUSTER_KEY, MIN(q.WAREHOUSE_NAME) AS WAREHOUSE_NAME, MIN(q.WAREHOUSE_SIZE) AS WAREHOUSE_SIZE, COUNT(*) AS EXECUTIONS, AVG(q.BYTES_SPILLED_TO_LOCAL_STORAGE) AS AVG_LOCAL_SPILL_BYTES, AVG(q.BYTES_SPILLED_TO_REMOTE_STORAGE) AS AVG_REMOTE_SPILL_BYTES, AVG(q.EXECUTION_TIME) AS AVG_EXECUTION_MS, COALESCE(SUM(a.CREDITS_ATTRIBUTED_COMPUTE), 0) AS CREDITS, (SELECT t.WAREHOUSE_SIZE FROM DETECTORS._SIZE_CREDITS AS t WHERE t.CREDITS_PER_HOUR > (SELECT s.CREDITS_PER_HOUR FROM DETECTORS._SIZE_CREDITS AS s WHERE s.WAREHOUSE_SIZE = MIN(q.WAREHOUSE_SIZE)) ORDER BY t.CREDITS_PER_HOUR LIMIT 1) AS TARGET_SIZE FROM HARVEST.QUERY_HISTORY AS q LEFT JOIN HARVEST.QUERY_ATTRIBUTION_HISTORY AS a ON a.QUERY_ID = q.QUERY_ID WHERE NOT q.WAREHOUSE_NAME IS NULL GROUP BY q.QUERY_PARAMETERIZED_HASH) SELECT *, COALESCE((AVG_REMOTE_SPILL_BYTES >= 1073741824 OR AVG_LOCAL_SPILL_BYTES >= 53687091200), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-PERF-03: Poor pruning on large, frequently filtered tables
CREATE OR REPLACE VIEW DETECTORS.DX_PERF_03 AS WITH __signals AS (WITH r AS (SELECT ah.OBJECT_NAME, q.QUERY_ID, q.PARTITIONS_SCANNED, q.PARTITIONS_TOTAL, COALESCE(a.CREDITS_ATTRIBUTED_COMPUTE, 0) AS CREDITS FROM HARVEST.ACCESS_HISTORY AS ah JOIN HARVEST.QUERY_HISTORY AS q ON q.QUERY_ID = ah.QUERY_ID LEFT JOIN HARVEST.QUERY_ATTRIBUTION_HISTORY AS a ON a.QUERY_ID = q.QUERY_ID WHERE ah.ACCESS_TYPE = 'READ' AND q.PARTITIONS_TOTAL >= 10000) SELECT t.FQ_NAME AS OBJECT_NAME, t.FQ_NAME AS CLUSTER_KEY, t.BYTES AS TABLE_BYTES, t.BYTES / 1099511627776 AS TABLE_TB, t.CLUSTERING_KEY, COUNT(r.QUERY_ID) AS LARGE_SCANS, COUNT(IFF(r.PARTITIONS_SCANNED >= 0.8 * r.PARTITIONS_TOTAL, r.QUERY_ID, NULL)) AS POOR_PRUNING_SCANS, COALESCE(SUM(IFF(r.PARTITIONS_SCANNED >= 0.8 * r.PARTITIONS_TOTAL, r.CREDITS, NULL)), 0) AS POOR_PRUNING_CREDITS, (SELECT MIN(c.COLUMN_NAME) FROM HARVEST.COLUMNS AS c WHERE c.FQ_NAME = t.FQ_NAME AND REGEXP_LIKE(c.COLUMN_NAME, '(?i)_DATE$')) AS SUGGESTED_KEY FROM HARVEST.TABLES AS t LEFT JOIN r ON r.OBJECT_NAME = t.FQ_NAME GROUP BY t.FQ_NAME, t.BYTES, t.CLUSTERING_KEY) SELECT *, COALESCE((CLUSTERING_KEY IS NULL AND TABLE_BYTES >= 1099511627776 AND POOR_PRUNING_SCANS >= 100), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-PERF-04: Costly query signatures with anti-patterns
CREATE OR REPLACE VIEW DETECTORS.DX_PERF_04 AS WITH __signals AS (WITH sig AS (SELECT q.QUERY_PARAMETERIZED_HASH AS H, MIN(q.QUERY_TEXT) AS SAMPLE_TEXT, MIN(q.WAREHOUSE_NAME) AS WAREHOUSE_NAME, COUNT(*) AS EXECUTIONS, AVG(q.ROWS_PRODUCED) AS AVG_ROWS_PRODUCED, AVG(q.EXECUTION_TIME) AS AVG_EXECUTION_MS, COALESCE(SUM(a.CREDITS_ATTRIBUTED_COMPUTE), 0) AS CREDITS FROM HARVEST.QUERY_HISTORY AS q LEFT JOIN HARVEST.QUERY_ATTRIBUTION_HISTORY AS a ON a.QUERY_ID = q.QUERY_ID WHERE q.QUERY_TYPE = 'SELECT' GROUP BY q.QUERY_PARAMETERIZED_HASH), flags AS (SELECT *, RANK() OVER (ORDER BY CREDITS DESC NULLS LAST) AS COST_RANK, CASE WHEN REGEXP_LIKE(SAMPLE_TEXT, '(?is)select\\s+\\*.*\\bjoin\\b') THEN 1 ELSE 0 END AS SELECT_STAR_JOIN, CASE WHEN REGEXP_LIKE(SAMPLE_TEXT, '(?i)where\\s+(to_char|to_varchar|upper|lower|trim|cast|date_trunc)\\s*\\(') THEN 1 ELSE 0 END AS NON_SARGABLE, CASE WHEN AVG_ROWS_PRODUCED >= 100000000 THEN 1 ELSE 0 END AS EXPLODING_JOIN FROM sig) SELECT H AS OBJECT_NAME, H AS CLUSTER_KEY, WAREHOUSE_NAME, EXECUTIONS, AVG_ROWS_PRODUCED, AVG_EXECUTION_MS, CREDITS, COST_RANK, SELECT_STAR_JOIN, NON_SARGABLE, EXPLODING_JOIN, SELECT_STAR_JOIN + NON_SARGABLE + EXPLODING_JOIN AS ANTI_PATTERNS, SAMPLE_TEXT FROM flags) SELECT *, COALESCE((COST_RANK <= 10 AND ANTI_PATTERNS >= 2), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-REL-01: Failing or retried tasks
CREATE OR REPLACE VIEW DETECTORS.DX_REL_01 AS WITH __signals AS (WITH RECURSIVE edges AS (SELECT TRIM(p.PRED) AS PARENT, t.FQ_NAME AS CHILD FROM HARVEST.TASKS AS t, TABLE(FLATTEN(INPUT => SPLIT(t.PREDECESSORS, ','))) AS p(seq, key, path, index, PRED, this) WHERE NOT t.PREDECESSORS IS NULL), down AS (SELECT PARENT AS ROOT, CHILD, 1 AS DEPTH FROM edges UNION ALL SELECT d.ROOT, e.CHILD, d.DEPTH + 1 FROM down AS d JOIN edges AS e ON e.PARENT = d.CHILD WHERE d.DEPTH < 64), up AS (SELECT CHILD AS TASK, PARENT AS ANCESTOR, 1 AS DEPTH FROM edges UNION ALL SELECT u.TASK, e.PARENT, u.DEPTH + 1 FROM up AS u JOIN edges AS e ON e.CHILD = u.ANCESTOR WHERE u.DEPTH < 64), h AS (SELECT FQ_NAME, COUNT(*) AS RUNS, COUNT_IF(STATE = 'FAILED') AS FAILURES, COUNT_IF(ATTEMPT_NUMBER > 1) AS RETRIES, MAX(ERROR_MESSAGE) AS LAST_ERROR FROM HARVEST.TASK_HISTORY GROUP BY FQ_NAME), blast AS (SELECT d.ROOT, LISTAGG(DISTINCT d.CHILD, ', ') WITHIN GROUP (ORDER BY d.CHILD) AS DOWNSTREAM_TASKS, COUNT(DISTINCT d.CHILD) AS DOWNSTREAM_COUNT FROM down AS d GROUP BY d.ROOT), skipped AS (SELECT d.ROOT, COUNT(*) AS DOWNSTREAM_SKIPPED_RUNS FROM down AS d JOIN HARVEST.TASK_HISTORY AS th ON th.FQ_NAME = d.CHILD AND th.STATE = 'SKIPPED' GROUP BY d.ROOT) SELECT t.FQ_NAME AS OBJECT_NAME, COALESCE((SELECT MAX(u.ANCESTOR) FROM up AS u WHERE u.TASK = t.FQ_NAME AND u.DEPTH = (SELECT MAX(u2.DEPTH) FROM up AS u2 WHERE u2.TASK = t.FQ_NAME)), t.FQ_NAME) AS CLUSTER_KEY, t.WAREHOUSE, t.TARGET_TABLE, t.PREDECESSORS, COALESCE(h.RUNS, 0) AS RUNS, COALESCE(h.FAILURES, 0) AS FAILURES, COALESCE(h.RETRIES, 0) AS RETRIES, CASE WHEN COALESCE(h.RUNS, 0) > 0 THEN h.FAILURES / h.RUNS ELSE 0 END AS FAILURE_RATE, h.LAST_ERROR, b.DOWNSTREAM_TASKS, COALESCE(b.DOWNSTREAM_COUNT, 0) AS DOWNSTREAM_COUNT, COALESCE(s.DOWNSTREAM_SKIPPED_RUNS, 0) AS DOWNSTREAM_SKIPPED_RUNS FROM HARVEST.TASKS AS t LEFT JOIN h ON h.FQ_NAME = t.FQ_NAME LEFT JOIN blast AS b ON b.ROOT = t.FQ_NAME LEFT JOIN skipped AS s ON s.ROOT = t.FQ_NAME) SELECT *, COALESCE((FAILURE_RATE >= 0.05 AND FAILURES >= 3), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-REL-02: Freshness SLA misses on Tier-1 tables
CREATE OR REPLACE VIEW DETECTORS.DX_REL_02 AS WITH __signals AS (WITH sla AS (SELECT IFF(_u.pos = _u_2.pos_2, _u_2.col, NULL) AS col FROM HARVEST.CLIENT_INPUTS CROSS JOIN TABLE(FLATTEN(INPUT => ARRAY_GENERATE_RANGE(0, (GREATEST(ARRAY_SIZE(FROM_JSON(VALUE, '[{"table":"VARCHAR","loaded_by":"VARCHAR","deadline_utc":"VARCHAR"}]'))) - 1) + 1))) AS _u(seq, key, path, index, pos, this) CROSS JOIN TABLE(FLATTEN(INPUT => FROM_JSON(VALUE, '[{"table":"VARCHAR","loaded_by":"VARCHAR","deadline_utc":"VARCHAR"}]'))) AS _u_2(seq, key, path, pos_2, col, this) WHERE KEY = 'freshness_slas' AND (_u.pos = _u_2.pos_2 OR (_u.pos > (ARRAY_SIZE(FROM_JSON(VALUE, '[{"table":"VARCHAR","loaded_by":"VARCHAR","deadline_utc":"VARCHAR"}]')) - 1) AND _u_2.pos_2 = (ARRAY_SIZE(FROM_JSON(VALUE, '[{"table":"VARCHAR","loaded_by":"VARCHAR","deadline_utc":"VARCHAR"}]')) - 1)))), days AS (SELECT DISTINCT CAST(SCHEDULED_TIME AS DATE) AS D FROM HARVEST.TASK_HISTORY), done AS (SELECT FQ_NAME, CAST(COMPLETED_TIME AS DATE) AS D, MIN(COMPLETED_TIME) AS FIRST_SUCCESS FROM HARVEST.TASK_HISTORY WHERE STATE = 'SUCCEEDED' GROUP BY FQ_NAME, CAST(COMPLETED_TIME AS DATE)), daily AS (SELECT sla."table" AS TABLE_NAME, sla.loaded_by AS LOADED_BY, sla.deadline_utc AS DEADLINE_UTC, days.D, CASE WHEN done.FIRST_SUCCESS IS NULL OR CAST(done.FIRST_SUCCESS AS TIME) > CAST(sla.deadline_utc AS TIME) THEN 1 ELSE 0 END AS MISSED, DATEDIFF(MINUTE, days.D + CAST(sla.deadline_utc AS TIME), done.FIRST_SUCCESS) AS LATE_MINUTES FROM sla CROSS JOIN days LEFT JOIN done ON done.FQ_NAME = sla.loaded_by AND done.D = days.D) SELECT TABLE_NAME AS OBJECT_NAME, LOADED_BY AS CLUSTER_KEY, LOADED_BY, DEADLINE_UTC, COUNT(*) AS SLA_DAYS, SUM(MISSED) AS MISSED_DAYS, SUM(MISSED) / COUNT(*) AS MISS_RATE, COALESCE(MAX(IFF(MISSED = 1, LATE_MINUTES, NULL)), 0) AS MAX_LATE_MINUTES, CASE WHEN TABLE_NAME IN (SELECT FQ_NAME FROM DETECTORS._TIER1_TABLES) THEN 1 ELSE 0 END AS IS_TIER1 FROM daily GROUP BY TABLE_NAME, LOADED_BY, DEADLINE_UTC) SELECT *, COALESCE((IS_TIER1 = 1 AND MISS_RATE >= 0.05), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-REL-03: Pipelines running under personal credentials
CREATE OR REPLACE VIEW DETECTORS.DX_REL_03 AS WITH __signals AS (SELECT q.USER_NAME AS OBJECT_NAME, q.USER_NAME AS CLUSTER_KEY, COALESCE(MIN(u.TYPE), 'PERSON') AS USER_TYPE, COUNT(*) AS EXECUTIONS, COUNT(DISTINCT CAST(q.START_TIME AS DATE)) AS RUN_DAYS, LISTAGG(DISTINCT q.QUERY_PARAMETERIZED_HASH, ', ') WITHIN GROUP (ORDER BY q.QUERY_PARAMETERIZED_HASH) AS SIGNATURES, LISTAGG(DISTINCT COALESCE(q.QUERY_TAG, '(none)'), ', ') WITHIN GROUP (ORDER BY COALESCE(q.QUERY_TAG, '(none)')) AS QUERY_TAGS, LISTAGG(DISTINCT q.CLIENT_APPLICATION_ID, ', ') WITHIN GROUP (ORDER BY q.CLIENT_APPLICATION_ID) AS CLIENT_APPS, MIN(q.ROLE_NAME) AS ROLE_NAME, UPPER(REGEXP_REPLACE(COALESCE(MIN(q.QUERY_TAG), q.USER_NAME), '[^A-Za-z0-9]+', '_', 'g')) AS PIPELINE_ID FROM HARVEST.QUERY_HISTORY AS q LEFT JOIN HARVEST.USERS AS u ON u.NAME = q.USER_NAME WHERE ARRAY_CONTAINS(CAST(q.QUERY_TYPE AS VARIANT), ['INSERT', 'MERGE', 'UPDATE', 'DELETE', 'COPY', 'CREATE_TABLE_AS_SELECT', 'INSERT_OVERWRITE']) GROUP BY q.USER_NAME) SELECT *, COALESCE((USER_TYPE = 'PERSON' AND RUN_DAYS >= 20), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-REL-04: Tier-1 data without replication or failover
CREATE OR REPLACE VIEW DETECTORS.DX_REL_04 AS WITH __signals AS (WITH rpo AS (SELECT k AS DATABASE_NAME, CAST(JSON_EXTRACT_PATH_TEXT(VALUE, '$."' || k || '"') AS DOUBLE) AS RPO_HOURS FROM HARVEST.CLIENT_INPUTS, TABLE(FLATTEN(INPUT => OBJECT_KEYS(VALUE))) AS t(seq, key, path, index, k, this) WHERE KEY = 'rpo_hours'), rep AS (SELECT TRIM(d.DB) AS DATABASE_NAME, g.NAME, CAST(REGEXP_SUBSTR(g.REPLICATION_SCHEDULE, '([0-9]+)\\s*MINUTE', 1, 1, 'c', 1) AS DOUBLE) / 60 AS SCHEDULE_HOURS FROM HARVEST.REPLICATION_GROUPS AS g, TABLE(FLATTEN(INPUT => SPLIT(g.ALLOWED_DATABASES, ','))) AS d(seq, key, path, index, DB, this)) SELECT rpo.DATABASE_NAME AS OBJECT_NAME, rpo.DATABASE_NAME AS CLUSTER_KEY, rpo.RPO_HOURS, COUNT(rep.NAME) AS REPLICATION_GROUPS, MIN(rep.SCHEDULE_HOURS) AS SCHEDULE_HOURS, rpo.RPO_HOURS * 60 * 0.5 AS TARGET_SCHEDULE_MINUTES, (SELECT MIN(ORGANIZATION_NAME) FROM HARVEST.ACCOUNT_INFO) AS ORGANIZATION_NAME, (SELECT MIN(ACCOUNT_NAME) FROM HARVEST.ACCOUNT_INFO) AS ACCOUNT_NAME FROM rpo LEFT JOIN rep ON rep.DATABASE_NAME = rpo.DATABASE_NAME GROUP BY rpo.DATABASE_NAME, rpo.RPO_HOURS) SELECT *, COALESCE((RPO_HOURS <= 24 AND (REPLICATION_GROUPS = 0 OR SCHEDULE_HOURS > RPO_HOURS)), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-SEC-01: Weak authentication
CREATE OR REPLACE VIEW DETECTORS.DX_SEC_01 AS WITH __signals AS (WITH l AS (SELECT USER_NAME, COUNT(*) AS LOGINS, COUNT_IF(FIRST_AUTHENTICATION_FACTOR = 'PASSWORD' AND SECOND_AUTHENTICATION_FACTOR IS NULL) AS SINGLE_FACTOR_LOGINS FROM HARVEST.LOGIN_HISTORY WHERE IS_SUCCESS = 'YES' GROUP BY USER_NAME) SELECT u.NAME AS OBJECT_NAME, CASE WHEN ARRAY_CONTAINS(CAST(COALESCE(u.TYPE, 'PERSON') AS VARIANT), ['SERVICE', 'LEGACY_SERVICE']) THEN 'service_password' ELSE 'human_without_mfa' END AS CLUSTER_KEY, COALESCE(u.TYPE, 'PERSON') AS USER_TYPE, u.HAS_PASSWORD, u.HAS_MFA, u.HAS_RSA_PUBLIC_KEY, CASE WHEN NOT u.EXT_AUTHN_UID IS NULL THEN 1 ELSE 0 END AS HAS_SSO, COALESCE(l.LOGINS, 0) AS LOGINS, COALESCE(l.SINGLE_FACTOR_LOGINS, 0) AS SINGLE_FACTOR_LOGINS FROM HARVEST.USERS AS u LEFT JOIN l ON l.USER_NAME = u.NAME WHERE NOT COALESCE(u.DISABLED, FALSE)) SELECT *, COALESCE(((CLUSTER_KEY = 'human_without_mfa' AND HAS_PASSWORD AND NOT HAS_MFA AND HAS_SSO = 0) OR (CLUSTER_KEY = 'service_password' AND HAS_PASSWORD)), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-SEC-02: ACCOUNTADMIN sprawl
CREATE OR REPLACE VIEW DETECTORS.DX_SEC_02 AS WITH __signals AS (WITH g AS (SELECT gu.GRANTEE_NAME, u.HAS_MFA, CASE WHEN NOT u.EXT_AUTHN_UID IS NULL THEN 1 ELSE 0 END AS HAS_SSO, u.CREATED_ON FROM HARVEST.GRANTS_TO_USERS AS gu LEFT JOIN HARVEST.USERS AS u ON u.NAME = gu.GRANTEE_NAME WHERE gu.ROLE = 'ACCOUNTADMIN'), ranked AS (SELECT *, ROW_NUMBER() OVER (ORDER BY HAS_SSO DESC NULLS LAST, HAS_MFA DESC NULLS LAST, CREATED_ON, GRANTEE_NAME) AS KEEP_RANK FROM g), used AS (SELECT COUNT(*) AS USAGE_QUERIES, COUNT(DISTINCT CAST(START_TIME AS DATE)) AS USAGE_DAYS, COUNT(DISTINCT USER_NAME) AS USAGE_USERS FROM HARVEST.QUERY_HISTORY WHERE ROLE_NAME = 'ACCOUNTADMIN') SELECT 'ACCOUNTADMIN' AS OBJECT_NAME, 'break_glass' AS CLUSTER_KEY, (SELECT COUNT(*) FROM g) AS GRANTEES, (SELECT LISTAGG(GRANTEE_NAME, ', ') WITHIN GROUP (ORDER BY GRANTEE_NAME) FROM g) AS GRANTEE_LIST, (SELECT LISTAGG(GRANTEE_NAME, ',') WITHIN GROUP (ORDER BY GRANTEE_NAME) FROM ranked WHERE KEEP_RANK > 2) AS REVOKE_CANDIDATES, used.USAGE_QUERIES, used.USAGE_DAYS, used.USAGE_USERS, used.USAGE_DAYS / (SELECT WINDOW_DAYS FROM CORE.RUN_CONTEXT) AS USAGE_DAY_SHARE FROM used) SELECT *, COALESCE((GRANTEES > 2 OR USAGE_DAY_SHARE > 0.1), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-SEC-03: Dormant users and orphan roles
CREATE OR REPLACE VIEW DETECTORS.DX_SEC_03 AS WITH __signals AS (SELECT u.NAME AS OBJECT_NAME, 'dormant_user' AS CLUSTER_KEY, DATEDIFF(DAY, COALESCE(u.LAST_SUCCESS_LOGIN, u.CREATED_ON), (SELECT AS_OF FROM CORE.RUN_CONTEXT)) AS DAYS_SINCE_LOGIN, CAST(NULL AS BIGINT) AS USER_GRANTS, CAST(NULL AS BIGINT) AS PARENT_ROLES, CAST(NULL AS VARCHAR) AS GRANTS_HELD FROM HARVEST.USERS AS u WHERE NOT COALESCE(u.DISABLED, FALSE) UNION ALL SELECT r.NAME, 'orphan_role', NULL, (SELECT COUNT(*) FROM HARVEST.GRANTS_TO_USERS AS gu WHERE gu.ROLE = r.NAME), (SELECT COUNT(*) FROM HARVEST.GRANTS_TO_ROLES AS gr WHERE gr.GRANTED_ON = 'ROLE' AND gr.NAME = r.NAME), (SELECT LISTAGG(gr.PRIVILEGE || '|' || gr.GRANTED_ON || '|' || COALESCE(gr.TABLE_CATALOG || '.', '') || COALESCE(gr.TABLE_SCHEMA || '.', '') || gr.NAME, ';') WITHIN GROUP (ORDER BY gr.PRIVILEGE, gr.NAME) FROM HARVEST.GRANTS_TO_ROLES AS gr WHERE gr.GRANTEE_NAME = r.NAME) FROM HARVEST.ROLES AS r WHERE NOT ARRAY_CONTAINS(CAST(r.NAME AS VARIANT), ['ACCOUNTADMIN', 'SECURITYADMIN', 'SYSADMIN', 'USERADMIN', 'ORGADMIN', 'PUBLIC'])) SELECT *, COALESCE(((CLUSTER_KEY = 'dormant_user' AND DAYS_SINCE_LOGIN >= 90) OR (CLUSTER_KEY = 'orphan_role' AND USER_GRANTS = 0 AND PARENT_ROLES = 0)), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-SEC-04: Missing network policy
CREATE OR REPLACE VIEW DETECTORS.DX_SEC_04 AS WITH __signals AS (SELECT 'ACCOUNT' AS OBJECT_NAME, 'network_policy' AS CLUSTER_KEY, a.NETWORK_POLICY AS ACCOUNT_POLICY, CASE WHEN a.NETWORK_POLICY IS NULL THEN 0 ELSE 1 END AS HAS_ACCOUNT_POLICY, (SELECT COUNT(*) FROM HARVEST.USERS AS u WHERE ARRAY_CONTAINS(CAST(u.TYPE AS VARIANT), ['SERVICE', 'LEGACY_SERVICE']) AND u.NETWORK_POLICY IS NULL) AS SERVICE_USERS_WITHOUT_POLICY, (SELECT LISTAGG(u.NAME, ', ') WITHIN GROUP (ORDER BY u.NAME) FROM HARVEST.USERS AS u WHERE ARRAY_CONTAINS(CAST(u.TYPE AS VARIANT), ['SERVICE', 'LEGACY_SERVICE']) AND u.NETWORK_POLICY IS NULL) AS SERVICE_USERS_LIST, (SELECT LISTAGG(DISTINCT REGEXP_SUBSTR(CLIENT_IP, '^([0-9]+\\.[0-9]+)\\.', 1, 1, 'c', 1) || '.0.0/16', ',') WITHIN GROUP (ORDER BY 1) FROM HARVEST.LOGIN_HISTORY WHERE IS_SUCCESS = 'YES' AND REGEXP_LIKE(CLIENT_IP, '^[0-9]+\\.[0-9]+\\.')) AS OBSERVED_CIDRS FROM HARVEST.ACCOUNT_INFO AS a) SELECT *, COALESCE((HAS_ACCOUNT_POLICY = 0 OR SERVICE_USERS_WITHOUT_POLICY > 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

-- DX-SEC-05: Sensitive columns without masking
CREATE OR REPLACE VIEW DETECTORS.DX_SEC_05 AS WITH __signals AS (WITH pii AS (SELECT OBJECT_DATABASE || '.' || OBJECT_SCHEMA || '.' || OBJECT_NAME AS TABLE_FQ, COLUMN_NAME, TAG_DATABASE || '.' || TAG_SCHEMA || '.' || TAG_NAME AS TAG_FQ, TAG_NAME, TAG_VALUE FROM HARVEST.TAG_REFERENCES WHERE DOMAIN = 'COLUMN' AND ARRAY_CONTAINS(CAST(UPPER(TAG_NAME) AS VARIANT), ['PII', 'SENSITIVE', 'PHI', 'PCI', 'CONFIDENTIAL'])), col_masked AS (SELECT REF_DATABASE_NAME || '.' || REF_SCHEMA_NAME || '.' || REF_ENTITY_NAME AS TABLE_FQ, REF_COLUMN_NAME FROM HARVEST.POLICY_REFERENCES WHERE POLICY_KIND = 'MASKING_POLICY' AND COALESCE(POLICY_STATUS, 'ACTIVE') = 'ACTIVE'), tag_masked AS (SELECT DISTINCT UPPER(TAG_NAME) AS TAG_NAME FROM HARVEST.POLICY_REFERENCES WHERE POLICY_KIND = 'MASKING_POLICY' AND NOT TAG_NAME IS NULL) SELECT pii.TABLE_FQ || '.' || pii.COLUMN_NAME AS OBJECT_NAME, pii.TABLE_FQ AS CLUSTER_KEY, pii.TAG_FQ, pii.TAG_VALUE, CASE WHEN NOT cm.REF_COLUMN_NAME IS NULL OR NOT tm.TAG_NAME IS NULL THEN 1 ELSE 0 END AS IS_MASKED FROM pii LEFT JOIN col_masked AS cm ON cm.TABLE_FQ = pii.TABLE_FQ AND cm.REF_COLUMN_NAME = pii.COLUMN_NAME LEFT JOIN tag_masked AS tm ON tm.TAG_NAME = UPPER(pii.TAG_NAME)) SELECT *, COALESCE((IS_MASKED = 0), FALSE) AS FLAGGED FROM __signals ORDER BY OBJECT_NAME, CLUSTER_KEY;

CREATE OR REPLACE PROCEDURE CORE.RUN_D0()
RETURNS VARCHAR LANGUAGE SQL EXECUTE AS OWNER AS
$$
DECLARE run_at TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP();
BEGIN
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-01', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_01 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-02', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_02 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-03', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_03 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-04', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_04 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-05', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_05 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-06', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_06 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-07', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_07 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-COST-08', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_COST_08 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-GOV-01', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_GOV_01 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-GOV-02', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_GOV_02 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-GOV-03', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_GOV_03 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-PERF-01', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_PERF_01 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-PERF-02', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_PERF_02 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-PERF-03', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_PERF_03 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-PERF-04', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_PERF_04 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-REL-01', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_REL_01 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-REL-02', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_REL_02 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-REL-03', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_REL_03 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-REL-04', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_REL_04 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-SEC-01', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_SEC_01 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-SEC-02', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_SEC_02 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-SEC-03', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_SEC_03 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-SEC-04', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_SEC_04 WHERE FLAGGED;
  INSERT INTO CORE.FINDINGS SELECT :run_at, 'DX-SEC-05', OBJECT_NAME, CLUSTER_KEY, OBJECT_CONSTRUCT(*) FROM DETECTORS.DX_SEC_05 WHERE FLAGGED;
  RETURN 'D0 snapshot complete';
END;
$$;

CREATE OR REPLACE VIEW CORE.TOP_FINDINGS AS SELECT CHECK_ID, COUNT(*) AS OBJECTS, ARRAY_AGG(OBJECT_NAME) AS AFFECTED FROM CORE.FINDINGS WHERE RUN_AT = (SELECT MAX(RUN_AT) FROM CORE.FINDINGS) GROUP BY CHECK_ID;

GRANT USAGE ON SCHEMA CORE TO APPLICATION ROLE APP_VIEWER;

GRANT USAGE ON SCHEMA DETECTORS TO APPLICATION ROLE APP_VIEWER;

GRANT SELECT ON ALL VIEWS IN SCHEMA DETECTORS TO APPLICATION ROLE APP_VIEWER;

